package id.yanuar.bf01.ui

/**
 * Logo bitmaps of the Hi! profile QR codes. GENERATED from the BF firmware drawing code
 * (bf01-firmware ui/bf_yan.c, yan_draw_logo), so the app preview and the BF screen show the same pixels.
 * Each logo is 40x40, 1 bit per pixel, 10 hex digits per row, logo centre at (20,20).
 * Keys: wa waw ig li yt gh tt fb x tg em web link, and "#A".."#Z", "#0".."#9" (letter badge).
 */
internal object LogoBits {
    const val SIZE = 40
    private val HEX = mapOf(
        "wa" to "",
        "waw" to "",
        "ig" to "",
        "li" to "",
        "yt" to "",
        "gh" to "",
        "tt" to "",
        "fb" to "",
        "x" to "",
        "tg" to "",
        "em" to "",
        "web" to "",
        "link" to "",
        "#A" to "",
        "#B" to "",
        "#C" to "",
        "#D" to "",
        "#E" to "",
        "#F" to "",
        "#G" to "",
        "#H" to "",
        "#I" to "",
        "#J" to "",
        "#K" to "",
        "#L" to "",
        "#M" to "",
        "#N" to "",
        "#O" to "",
        "#P" to "",
        "#Q" to "",
        "#R" to "",
        "#S" to "",
        "#T" to "",
        "#U" to "",
        "#V" to "",
        "#W" to "",
        "#X" to "",
        "#Y" to "",
        "#Z" to "",
        "#0" to "",
        "#1" to "",
        "#2" to "",
        "#3" to "",
        "#4" to "",
        "#5" to "",
        "#6" to "",
        "#7" to "",
        "#8" to "",
        "#9" to ""
    )
    private val cache = HashMap<String, BooleanArray>()
    val keys: Set<String> get() = HEX.keys

    /** 40*40 pixels (row major, true = black) or null for an unknown key. */
    fun pixels(key: String): BooleanArray? = HEX[key]?.let { hex -> cache.getOrPut(key) {
        BooleanArray(SIZE * SIZE) { i -> val d = Character.digit(hex[i / 4], 16); (d shr (3 - i % 4)) and 1 == 1 } } }
}
